import {createAdminAuth} from '../admin-auth.mjs';import {publicBackendConfig} from '../../backend/public-config.mjs';
export function createCMSRepository({token=()=>createAdminAuth().accessToken(),config=publicBackendConfig,request=globalThis.fetch}={}){
 const send=async(resource,{method='GET',body,query=''}={})=>{if(!['hub_article_library','hub_article_revisions','rpc/save_hub_article','hub_article_draft_imports','rpc/save_hub_docx_import'].includes(resource))throw Error('Unsupported CMS resource.');const value=await token();const r=await request(config.url+'/rest/v1/'+resource+query,{method,headers:{apikey:config.publishableKey,Authorization:'Bearer '+value,'Content-Type':'application/json'},...body===undefined?{}:{body:JSON.stringify(body)}});const data=await r.json();if(!r.ok)throw Error(data.message||'CMS request unavailable.');return data;};
 return {imports:id=>send('hub_article_draft_imports',{query:'?select=*&article_id=eq.'+encodeURIComponent(id)+'&order=edit_version.desc'}),importDraft:(article,content)=>send('rpc/save_hub_docx_import',{method:'POST',body:{p_id:article.id,p_expected_version:article.edit_version,p_content:content}}),list:()=>send('hub_article_library',{query:'?select=*&order=updated_at.desc'}),history:id=>send('hub_article_revisions',{query:'?select=*&article_id=eq.'+encodeURIComponent(id)+'&order=revision_number.desc'}),save:(article,content,action='DRAFT',revision=null)=>send('rpc/save_hub_article',{method:'POST',body:{p_id:article?.id||null,p_expected_version:article?.edit_version||null,p_content:content,p_action:action,p_restore_revision:revision}})};
}
